"""Secrets in the macOS login Keychain (via `keyring`). Nothing secret is ever written to disk by meetcap."""
from __future__ import annotations

from typing import Callable

SERVICE = "meetcap"

KNOWN_SECRETS = {
    "obs-password": "OBS websocket password (generated by `meetcap setup-obs`)",
    "speech-key": "Azure AI Speech resource key (only when azure.speech.auth = key)",
    "openai-key": "Azure OpenAI key (only when azure.openai.auth = key)",
    "storage-connection-string": "Storage connection string (only when azure.storage.auth = key)",
    "storage-sas-url": "Container SAS URL (only when azure.storage.auth = sas)",
    "groq-key": "Groq API key (transcription or notes with Groq)",
    "openrouter-key": "OpenRouter API key (transcription or notes with OpenRouter)",
    "anthropic-key": "Anthropic API key (notes with Claude)",
    "openai-api-key": "OpenAI API key (transcription or notes with OpenAI)",
}

SecretGetter = Callable[[str], "str | None"]


def get_secret(name: str) -> str | None:
    import keyring

    return keyring.get_password(SERVICE, name)


def set_secret(name: str, value: str) -> None:
    import keyring

    if name not in KNOWN_SECRETS:
        raise KeyError(f"Unknown secret '{name}'. Known: {', '.join(KNOWN_SECRETS)}")
    keyring.set_password(SERVICE, name, value)


def delete_secret(name: str) -> None:
    import keyring
    from keyring.errors import PasswordDeleteError

    try:
        keyring.delete_password(SERVICE, name)
    except PasswordDeleteError:
        pass


def require(getter: SecretGetter, name: str) -> str:
    value = getter(name)
    if not value:
        raise RuntimeError(f"Secret '{name}' is missing. Run: meetcap secret set {name}")
    return value
